namespace Core.Usage;
// 注释里写 row.Outcome == "succeeded" 不算。
static class Good
{
    static bool Done(UsageRow row) => row.Outcome == UsageOutcome.Succeeded;
    static string Name(UsageKind kind) => kind switch { UsageKind.Inference => "推理", UsageKind.Estimate => "估算", UsageKind.Models => "模型查询" };
    static (string, string?) Classify() => ("cancelled", null);
    static bool Other(string type) => type == "connection_failed";
}

namespace Core.Usage;
static class Bad
{
    static bool Done(string outcome) => outcome == "succeeded";
    static bool Started(string outcome) => "started" != outcome;
}

namespace Core.Usage;
static class Bad
{
    static string Label(string state) => state switch
    {
        "passed" => "通过",
        "failed" when state.Length > 0 => "失败",
        _ => "未检测"
    };
    static bool Partial(string value) => value is "cancelled" or "interrupted";
}
